import {text as e,icon,avatar} from './components.js';
import {interestChoices} from './onboarding.js';
function portrait(candidate,hero=false){
  let url='';
  try { const parsed=new URL(candidate?.avatarUrl||''); if(parsed.protocol==='https:'&&!parsed.username&&!parsed.password)url=parsed.href; } catch {}
  return url?`<img class="echo-portrait-photo" data-avatar-fallback="${e(Array.from(candidate?.name||'?')[0])}" src="${e(url)}" alt="${e(candidate.name||'')} 的头像" width="440" height="528" referrerpolicy="no-referrer" ${hero?'fetchpriority="high"':'loading="lazy"'}>`:avatar(candidate?.name||candidate?.address||'');
}
const action=(label,name,attrs='',cls='')=>`<button class="btn ${cls}" data-action="${name}" ${attrs}>${label}</button>`;
const heading=(title,sub)=>`<header class="head"><h1>${title}</h1><p>${sub}</p></header>`;
export function communityView(state){
  const candidate=state.candidates.find(c=>c.address===state.echoAddress),preview=state.preview||state.previewOnly;
  const back=action(icon('back')+' 共鸣雷达','discover','','light compact');
  if(state.route==='echo-results')return resultsView(state,back,preview);
  if(state.route==='echo-detail')return detailView(state,candidate,back);
  if(state.route==='echo-chat'&&!state.echoAddress&&state.connections?.length)return back+heading('Echo Connections','每一份回应，都由你自己决定。')+state.connections.map(connection=>{const incoming=connection.recipient.toLowerCase()===state.user?.toLowerCase(),peer=incoming?connection.requester:connection.recipient;return `<article class="card"><div class="row">${avatar(peer)}<div><h3>${e(peer.slice(0,6)+'…'+peer.slice(-4))}</h3><p class="small muted">${e({pending:'等待回应',accepted:'已同意连接',declined:'已拒绝',blocked:'已屏蔽'}[connection.status]||connection.status)}</p></div></div><div class="actions">${incoming&&connection.status==='pending'?action('接受连接','connection-respond',`data-id="${e(connection.id)}" data-decision="accept"`,'rose')+action('暂不连接','connection-respond',`data-id="${e(connection.id)}" data-decision="decline"`,'light'):''}${action('查看连接空间','echo-chat',`data-address="${e(peer)}"`,'light')}</div></article>`;}).join('');
  if(state.route==='echo-chat')return '<section class="stitch-chat">'+chatView(state,candidate,back)+'</section>';
  return undefined;
}
function chatView(state,candidate,back){
  const connection=(state.connections||[]).find(c=>[c.requester,c.recipient].some(a=>a.toLowerCase()===state.echoAddress?.toLowerCase()));
  const incoming=connection?.status==='pending'&&connection.recipient.toLowerCase()===state.user?.toLowerCase();
  const status={pending:'等待回应',accepted:'已同意连接',declined:'已拒绝',blocked:'连接已屏蔽'};
  const response=incoming?`<div class="actions">${action('接受连接','connection-respond',`data-id="${e(connection.id)}" data-decision="accept"`,'rose')}${action('暂不连接','connection-respond',`data-id="${e(connection.id)}" data-decision="decline"`,'light')}</div>`:!connection&&candidate?action('发送连接请求','echo-connect',`data-address="${e(candidate.address)}"`,'rose'):'';
  const name=candidate?.name||state.echoAddress;
  const header=`<div class="bell-chat-header">${portrait(candidate||{address:state.echoAddress})}<div><h2>${e(name||'Echo Chat')}</h2><small>${connection?e(status[connection.status]||connection.status):'尚未建立连接'}</small></div></div>`;
  if(connection?.status!=='accepted')return back+header+`<div class="bell-conversation"><span class="pill">这是你们开始了解的地方</span><div class="bell-empty-art">${icon('heart')}<h3>先从一次双向的同意开始</h3><p>${connection?.status==='pending'?'连接请求已保存在服务器，等待对方独立决定。':'连接请求会发送给真实账户，对方可以接受或拒绝。'}</p>${response}</div></div><p class="small muted">双方同意后，这里才会打开端到端加密的对话空间。</p>`;
  const ephemeral=Boolean(state.ephemeralRoom),messages=state.chatMessages||[];
  const time=at=>new Date(at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});
  const bubble=m=>`<div class="bell-chat-bubble ${m.mine?'mine':'theirs'}${m.expires_at?' is-ephemeral':''}">${m.error?`<p class="small muted">${e(m.error)}</p>`:`<p>${e(m.content?.text||'')}</p>`}<small>${m.mine?'你':e(name||'对方')} · ${e(time(m.content?.at||m.created_at))}${m.expires_at?' · 阅后即焚':''}</small></div>`;
  return back+header+(ephemeral?`<aside class="bell-ephemeral-note">${icon('clock')}<div><h3>阅后即焚空间</h3><p>从这里发出的消息只保留 24 小时，之后由服务器自动删除，双方都无法找回。</p></div></aside>`:'')+`<div class="bell-conversation">${messages.length?messages.map(bubble).join(''):`<div class="bell-empty-art">${icon('spark')}<h3>${ephemeral?'说一句只属于此刻的话':'第一句话，由你来写'}</h3><p>A quiet space for your first hello.</p></div>`}</div><form class="bell-composer" data-form="chat-compose"><label class="sr-only" for="chat-message">加密消息</label><input id="chat-message" name="message" maxlength="2000" placeholder="${ephemeral?'写一句只保留 24 小时的话…':'写一句想说的话…'}" autocomplete="off" value="${e(state.chatDraftPeer===state.echoAddress?state.chatDraft||'':'')}"><button class="icon" type="submit" aria-label="发送加密消息">${icon('send')}</button></form><div class="actions">${action(ephemeral?'返回常驻对话':'进入阅后即焚空间','ephemeral-toggle','','light compact')}</div><details class="echo-chat-privacy"><summary>${icon('shield')} 私密对话</summary><p class="small muted">${ephemeral?'这些消息将在 24 小时后被服务器删除。':'消息在本机加密；服务器仅保存密文，直到一方屏蔽连接。'}双方需登记加密密钥后才能发送。</p></details>`;
}
function connectionFor(state,address){return (state.connections||[]).find(c=>[c.requester,c.recipient].some(a=>a.toLowerCase()===address?.toLowerCase()));}
function resultsView(state,back,preview){
  return back+heading('People who might resonate','先看见一个人，再决定是否靠近。')+(state.candidates.length?`<div class="bell-result-summary"><span>${icon('spark')} ${state.candidates.length} 位公开资料</span><small>来自共同兴趣与关系意向</small></div><div class="bell-echo-grid">${state.candidates.map(c=>{
    const shared=c.interests.filter(i=>state.profile?.interests?.includes(i)),connection=connectionFor(state,c.address);
    return `<article class="bell-echo-card"><button class="bell-portrait" data-action="echo-detail" data-address="${e(c.address)}" aria-label="查看 ${e(c.name)}">${portrait(c)}<span class="bell-portrait-caption">${icon('spark')}${shared.length?'共同喜欢 '+e(shared.slice(0,2).join(' · ')):'从一次了解开始'}</span></button><div class="row"><h2>${e(c.name)}${c.age?', '+e(c.age):''}</h2>${connection?.status==='accepted'?'<span class="pill ok">已同意连接</span>':''}</div><p class="small muted">${icon('pin')}${e(c.city||'城市未填写')}</p><div class="chips">${c.interests.map(i=>`<span class="pill">${e(i)}</span>`).join('')}</div><p class="bell-card-introduction">${e(c.statement||'让第一次对话，成为了解的开始。')}</p><div class="row">${action(icon('heart'),'radar-save',`data-address="${e(c.address)}" aria-label="${c.saved?'取消收藏':'收藏'} ${e(c.name)}" aria-pressed="${Boolean(c.saved)}"`,'light compact')}${action('了解彼此 '+icon('next'),'echo-detail',`data-address="${e(c.address)}"`,'rose compact')}</div></article>`;
  }).join('')}</div>`:`<div class="bell-empty-art">${icon('bell')}<h2>等待一份真实的共鸣</h2><p>登录并完善资料后，开始寻找与你兴趣相近的人。</p>${action(preview?'连接钱包':'重新探测',preview?'login':'discover')}</div>`);
}
function detailView(state,candidate,back){
  if(!candidate)return back+heading('Possible Echo','先在共鸣雷达选择一位真实候选人。')+action('查看推荐结果','echo-results');
  const connection=connectionFor(state,candidate.address),accepted=connection?.status==='accepted',pending=connection?.status==='pending';
  const incoming=pending&&connection.recipient.toLowerCase()===state.user?.toLowerCase();
  const common=candidate.interests.filter(i=>state.profile?.interests?.includes(i));
  const sharedIntention=Boolean(candidate.intention&&candidate.intention===state.profile?.intention),sharedCity=Boolean(candidate.city&&candidate.city===state.profile?.city);
  const intentions={'Serious relationship':'认真建立关系','Open to connection':'先认识彼此','Already in love':'已有伴侣','Just exploring':'先探索一下'};
  const status={pending:'等待回应',accepted:'双方已同意',declined:'对方暂不连接',blocked:'连接已屏蔽'};
  const title=accepted?candidate.name+' Heard Your Chime':pending?'Your Chime Is on Its Way':'A Possible Resonance';
  const prompt=common.length?'你好，看到我们都喜欢'+common.slice(0,2).join('和')+'。最近有没有让你印象深刻的一次体验？':'你好，很高兴在这里遇见你。最近有什么让你感到开心的小事吗？';
  const reasons=[{title:common.length?common.slice(0,2).join(' & '):'Curated Interests',text:common.length?'你们都喜欢 '+common.join(' · ')+'。从一段真实的体验聊起。':candidate.interests.length?'对方公开了 '+candidate.interests.join(' · ')+'，可以先了解彼此的兴趣。':'对方还没有填写兴趣。',icon:'image'},
    {title:'Slow Devotion & Clarity',text:sharedIntention?'你们都选择了「'+(intentions[candidate.intention]||candidate.intention)+'」。让相处从真诚与清晰开始。':candidate.intention?'对方的关系意向是「'+(intentions[candidate.intention]||candidate.intention)+'」。可以先问问彼此期待怎样的相处。':'对方还没有填写关系意向。',icon:'heart'},
    {title:'Everyday Orbit',text:sharedCity?'你们都在 '+candidate.city+'。也许可以从各自喜欢的城市角落开始了解。':candidate.city?'对方填写的城市是 '+candidate.city+'。聊聊你们各自喜欢的城市角落。':'对方还没有填写城市。',icon:'pin'}];
  const fragments=candidate.interests.slice(0,3).map(interest=>{const choice=interestChoices.find(([value])=>value===interest);return `<figure class="echo-fragment">${choice?`<img src="/assets/${choice[2]}" alt="" width="160" height="108" loading="lazy">`:icon('spark')}<figcaption>${e(choice?.[1]||interest)}<small>${e(interest)}</small></figcaption></figure>`;}).join('');
  const controls=incoming?action('回应这声 Bell · 接受连接','connection-respond',`data-id="${e(connection.id)}" data-decision="accept"`,'rose')+action('暂不连接','connection-respond',`data-id="${e(connection.id)}" data-decision="decline"`,'light'):accepted?action('Start Echo Chat '+icon('next'),'echo-chat',`data-address="${e(candidate.address)}"`,'echo-primary'):pending?action('查看等待中的请求','echo-chat',`data-address="${e(candidate.address)}"`,'echo-primary'):!connection?action(icon('bell')+' Ring Their Bell','echo-connect',`data-address="${e(candidate.address)}"`,'echo-primary'):'<p class="notice">这份连接已结束，请尊重彼此的选择。</p>';
  return '<section class="echo-persona">'+`<aside class="echo-status ${accepted?'connected':pending?'pending':''}" role="status">${icon('bell')}<div><h2>${e(title)}</h2><p>${accepted?'Mutual Match · 你们的私密对话空间已开启。':pending?incoming?'对方想与你继续了解，由你决定是否回应。':'你的连接请求已送达，等待对方独立回应。':connection?e(status[connection.status]||connection.status):'先看见一个人，再决定是否靠近。'}</p></div></aside>
  <article class="bell-profile-card echo-profile"><div class="bell-profile-hero ${candidate.avatarUrl?'has-photo':''}">${portrait(candidate,true)}<div class="echo-portrait-identity"><span class="bell-profile-label">${icon('spark')}${common.length?'共同兴趣 · '+common.length+' 项':'Curated Persona · 公开资料'}</span><h1>${e(candidate.name)}${candidate.age?', '+e(candidate.age):''}</h1><p>${e(candidate.occupation||'')}${candidate.occupation&&candidate.city?' · ':''}${e(candidate.city||'')}</p></div></div><div class="bell-profile-body"><div class="chips">${candidate.interests.map(i=>`<span class="pill">${e(i)}</span>`).join('')}</div><span class="eyebrow">PERSONAL MANIFESTO</span><blockquote class="bell-introduction">“${e(candidate.statement||'对方还没有填写个人宣言。')}”</blockquote></div></article>
  <section class="bell-reasons"><div class="row"><h2>Why You Resonated</h2></div>${reasons.map(reason=>`<article class="bell-reason"><span class="bell-setting-icon">${icon(reason.icon)}</span><div><h3>${e(reason.title)}</h3><p>${e(reason.text)}</p></div></article>`).join('')}</section>
  <section class="echo-fragments"><div class="row"><h2>Aesthetic Fragments</h2><span class="small muted">${Math.min(3,candidate.interests.length)} interests</span></div><div class="echo-fragment-grid">${fragments||'<p class="small muted">对方还没有分享兴趣切片。</p>'}</div></section>
  <aside class="echo-whisper"><div class="row"><span class="eyebrow">${icon('spark')} CONSENSUS WHISPER</span><span class="small muted">Icebreaker</span></div><p>${e(prompt)}</p>${accepted?action('Use This Prompt '+icon('next'),'echo-whisper',`data-address="${e(candidate.address)}" data-prompt="${e(prompt)}"`,'light compact'):'<p class="small muted">双向回应后，带着这句话开始聊天。</p>'}</aside>
  <div class="echo-gateway"><div class="echo-primary-row">${action(icon('bell'),'echo-chime','aria-label="试听一声 Bell"','light compact')}${controls}</div><div class="echo-gateway-links"><details class="echo-proof"><summary>${icon('shield')}查看连接凭证</summary><p>${connection?'连接记录：'+e(connection.id)+'<br>状态：'+e(status[connection.status]||connection.status):'目前尚无双方连接记录。'}</p><p>资料由用户公开填写；兴趣配图为示意。连接记录保存在链下，Soulbound Ring 需双方另行签名建立。</p></details></div>${action('了解 Ring 邀请','invite',`data-address="${e(candidate.address)}"`,'light')}</div></section>`;
}
